<script setup lang="ts">
import {ref,computed,onMounted,watch} from 'vue'
import {useRoute} from 'vue-router'
import SwotContextCollection from '@/components/SwotContextCollection.vue'
import PageHeader from '@/components/PageHeader.vue'
import {useAuthStore} from '@/stores/auth'
import {useOrganization} from '@/composables/useOrganization'
import {strategyAdmin,strategyAdminCommand} from '@/services/strategy-admin'
const route=useRoute()
const auth=useAuthStore(),{activeOrganization}=useOrganization()
const data=ref<any>({}),error=ref(''),notice=ref(''),busy=ref(false),showHidden=ref(false),selected=ref(String(route.query.campaign||'')),editing=ref<any>(null)
const states:Record<string,string>={draft:'Rascunho',open:'Em recolha',validation:'Em validação',closed:'Fechada',archived:'Arquivada'}
const quadrants:Record<string,string>={strengths:'Forças',weaknesses:'Fraquezas',opportunities:'Oportunidades',threats:'Ameaças'}
const campaigns=computed(()=>(data.value.swot_campaigns||[]).filter((r:any)=>showHidden.value||!r.is_demo&&r.status!=='archived'))
const campaign=computed(()=>(data.value.swot_campaigns||[]).find((r:any)=>r.id===selected.value))
const originals=computed(()=>(data.value.swot_contributions||[]).filter((r:any)=>r.campaign_id===selected.value))
const proposals=computed(()=>(data.value.swot_proposals||[]).filter((r:any)=>r.campaign_id===selected.value))
const contribution=ref({quadrant:'strengths',contribution:'',team_id:''}),importText=ref(''),transition=ref(''),reason=ref('')
const nextStates:Record<string,string[]>={draft:['open','archived'],open:['validation','closed','archived'],validation:['open','closed','archived'],closed:['open','archived'],archived:['draft','open']}
async function load(){data.value=await strategyAdmin('workspace');if(!campaigns.value.some((r:any)=>r.id===selected.value))selected.value=campaigns.value[0]?.id||''}
async function run(fn:()=>Promise<any>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();await load();notice.value='Alteração guardada.'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function edit(row?:any){editing.value=row?{...row,validators:(data.value.swot_campaign_validators||[]).filter((v:any)=>v.campaign_id===row.id).map((v:any)=>({user_id:v.user_id,team_id:v.team_id||''})),starts_at:row.starts_at?.slice(0,16)||'',ends_at:row.ends_at?.slice(0,16)||'',audience:(data.value.swot_campaign_audience||[]).filter((a:any)=>a.campaign_id===row.id).map((a:any)=>({kind:a.user_id?'user':'team',id:a.user_id||a.team_id}))}:{name:'',cycle_id:'',description:'',starts_at:'',ends_at:'',min_per_quadrant:0,max_per_quadrant:20,min_own:3,max_own:5,min_other:3,max_other:5,quota_mode:'participant_context',validators:[],is_demo:false,validation_rules:'Rever e validar os contributos antes da publicação na SWOT oficial.',audience:[]}}
function audienceChecked(kind:string,id:string){return editing.value.audience.some((a:any)=>a.kind===kind&&a.id===id)}
function toggleAudience(kind:string,id:string){const rows=editing.value.audience,index=rows.findIndex((a:any)=>a.kind===kind&&a.id===id);if(index<0)rows.push({kind,id});else rows.splice(index,1)}
async function save(){await run(async()=>{const p={...editing.value};for(const k of ['starts_at','ends_at'])p[k]=p[k]?new Date(p[k]).toISOString():null;const saved=await strategyAdminCommand('campaign_save',p.id||null,p);selected.value=saved.id;editing.value=null})}
async function add(){await run(async()=>{await strategyAdminCommand('contribution_add',selected.value,contribution.value);contribution.value.contribution=''})}
async function importRows(){await run(async()=>{const entries=importText.value.split(/\r?\n/).filter(x=>x.trim()).map(line=>{const [quadrant,text,author,team]=line.split('\t');const q=Object.keys(quadrants).find(k=>k===quadrant?.trim()||quadrants[k].toLowerCase()===quadrant?.trim().toLowerCase());const team_id=team?.trim()?(data.value.teams||[]).find((r:any)=>r.name===team.trim())?.id:null;if(team?.trim()&&!team_id)throw new Error(`Equipa não encontrada: ${team}`);return {quadrant:q,contribution:text,author_label:author,team_id,source:'Importação de folha de cálculo'}});await strategyAdminCommand('contribution_add',selected.value,{entries});importText.value=''})}
async function changeState(){await run(async()=>{await strategyAdminCommand('campaign_transition',selected.value,{status:transition.value,reason:reason.value,version:campaign.value.version});transition.value='';reason.value=''})}
async function remove(){if(confirm('Eliminar esta campanha? Só é possível se nunca tiver sido utilizada.'))await run(()=>strategyAdminCommand('campaign_delete',selected.value,{confirm_delete:true}))}
async function validate(p:any){if(confirm('Reveste o texto e o quadrante? Confirmas a publicação deste grupo na SWOT oficial?'))await run(()=>strategyAdminCommand('proposal_validate',selected.value,{proposal_id:p.id,title:p.title,quadrant:p.quadrant,human_confirmed:true}))}
watch(activeOrganization,()=>{selected.value='';editing.value=null;data.value={};void run(load)})
onMounted(()=>run(load))
</script>
<template><div class="campaign-page"><PageHeader><template #title>Campanhas SWOT</template><template #breadcrumb>Estratégia › Recolha e consolidação</template></PageHeader>
<p>A recolha preserva cada contributo original. Só os grupos revistos e aprovados passam para a SWOT oficial e para a TOWS.</p>
<div v-if="error" class="alert alert-danger" role="alert">{{error}}</div><div v-if="notice" class="alert alert-success" role="status">{{notice}}</div>
<div class="d-flex flex-wrap gap-3 mb-3"><select v-model="selected" class="form-select w-auto" aria-label="Campanha"><option value="">Selecionar campanha</option><option v-for="c in campaigns" :key="c.id" :value="c.id">{{c.name}} · {{states[c.status]}} {{c.is_demo?'(demonstração)':''}}</option></select><label><input v-model="showHidden" type="checkbox"> Mostrar demonstrações e arquivo</label><button v-if="auth.canManageStrategy" class="btn btn-primary" @click="edit()">Nova campanha</button><RouterLink class="btn btn-outline-primary" to="/estrategia/swot">SWOT oficial</RouterLink></div>
<section v-if="editing" class="sq-card p-3 mb-3"><h2 class="h5">{{editing.id?'Editar campanha':'Nova campanha'}}</h2><form novalidate @submit.prevent="save"><div class="row g-3">
<label class="col-md-6">Nome<input v-model="editing.name" class="form-control"></label><label class="col-md-6">Ciclo<select v-model="editing.cycle_id" class="form-select"><option value="">Seleciona um ciclo</option><option v-for="c in data.cycles" :key="c.id" :value="c.id">{{c.name}}</option></select></label>
<label class="col-12">Descrição opcional<textarea v-model="editing.description" class="form-control" placeholder="Explica o objetivo da campanha, se necessário"/></label><label class="col-md-6">Início da recolha<input v-model="editing.starts_at" type="datetime-local" class="form-control"></label><label class="col-md-6">Fim da recolha<input v-model="editing.ends_at" type="datetime-local" class="form-control"></label>
<label v-if="editing.quota_mode==='legacy'" class="col-md-6">Mínimo por quadrante<input v-model.number="editing.min_per_quadrant" type="number" min="0" class="form-control"></label><label v-if="editing.quota_mode==='legacy'" class="col-md-6">Máximo por quadrante<input v-model.number="editing.max_per_quadrant" type="number" min="1" class="form-control"></label>
<template v-if="editing.quota_mode!=='legacy'"><label v-for="f in [{key:'min_own',label:'Mínimo recomendado · por equipa'},{key:'max_own',label:'Máximo · por equipa'},{key:'min_other',label:'Mínimo recomendado · corporativa'},{key:'max_other',label:'Máximo · corporativa'}]" :key="f.key" class="col-md-6">{{f.label}}<input v-model.number="editing[f.key]" type="number" min="1" max="1000" class="form-control"></label><fieldset class="col-12"><legend class="h6">Responsáveis pela validação dos contextos</legend><p>Adiciona um responsável para a organização. Para cada equipa que recebe propostas, escolhe um responsável com atribuição ativa nessa equipa.</p><div v-for="(v,i) in editing.validators" :key="i" class="d-flex gap-2 mb-2"><select v-model="v.team_id" class="form-select" aria-label="Contexto a validar"><option value="">Organização</option><option v-for="t in data.teams?.filter((t:any)=>t.active)" :key="t.id" :value="t.id">{{t.name}}</option></select><select v-model="v.user_id" class="form-select" aria-label="Responsável pela validação"><option value="">Seleciona o responsável</option><option v-for="u in data.profiles?.filter((u:any)=>u.active)" :key="u.id" :value="u.id">{{u.full_name}}</option></select><button type="button" class="btn btn-outline-danger" @click="editing.validators.splice(i,1)">Remover</button></div><button type="button" class="btn btn-outline-primary" @click="editing.validators.push({user_id:'',team_id:''})">Adicionar responsável</button></fieldset></template><label class="col-12">Regras de validação<textarea v-model="editing.validation_rules" class="form-control"/></label><label class="col-12"><input v-model="editing.is_demo" type="checkbox"> Campanha de demonstração</label>
<fieldset class="col-md-6"><legend class="h6">Participantes</legend><label v-for="u in data.profiles?.filter((r:any)=>r.active)" :key="u.id" class="d-block"><input type="checkbox" :checked="audienceChecked('user',u.id)" @change="toggleAudience('user',u.id)"> {{u.full_name}}</label></fieldset>
<fieldset class="col-md-6"><legend class="h6">Equipas participantes</legend><label v-for="t in data.teams?.filter((r:any)=>r.active)" :key="t.id" class="d-block"><input type="checkbox" :checked="audienceChecked('team',t.id)" @change="toggleAudience('team',t.id)"> {{t.name}}</label></fieldset></div><p class="small sq-muted mt-2">Os gestores podem importar contributos. Os restantes utilizadores precisam de constar dos participantes ou de uma equipa selecionada.</p><button class="btn btn-primary" :disabled="busy">Guardar</button><button type="button" class="btn btn-secondary ms-2" @click="editing=null">Cancelar</button></form></section>
<template v-if="campaign"><p v-if="campaign.collection_revision!==2&&campaign.status==='draft'&&auth.canManageStrategy" class="alert alert-info">Este rascunho usa regras anteriores. <button class="btn btn-outline-primary" @click="run(()=>strategyAdminCommand('campaign_upgrade',selected,{}))">Atualizar para regras REV02</button></p><p v-if="campaign.quota_mode==='legacy'" class="alert alert-info">Esta campanha preserva as regras da recolha anterior. Para usar áreas temáticas obrigatórias e quotas por participante, cria uma nova campanha.</p><section class="sq-card p-3 mb-3"><div class="d-flex justify-content-between flex-wrap gap-2"><h2 class="h5">{{states[campaign.status]}}</h2><div v-if="auth.canManageStrategy"><button class="btn btn-outline-primary me-2" @click="edit(campaign)">Editar</button><button class="btn btn-outline-danger" @click="remove">Eliminar se não utilizada</button></div></div><p v-if="campaign.description" class="sq-muted">{{campaign.description}}</p><p>{{campaign.validation_rules}}</p><p v-if="campaign.quota_mode==='legacy'" class="small">Campanha anterior · limites por quadrante: {{campaign.min_per_quadrant}} a {{campaign.max_per_quadrant}} contributos.</p>
<form v-if="auth.canManageStrategy" class="d-flex gap-2 flex-wrap" novalidate @submit.prevent="changeState"><select v-model="transition" class="form-select w-auto" aria-label="Novo estado"><option value="">Mudar estado</option><option v-for="s in nextStates[campaign.status]||[]" :key="s" :value="s">{{states[s]}}</option></select><input v-model="reason" class="form-control w-auto flex-grow-1" placeholder="Motivo da alteração / reabertura" aria-label="Motivo"><button class="btn btn-outline-primary" :disabled="busy">Aplicar estado</button></form></section>
<SwotContextCollection v-if="campaign.quota_mode==='participant_context'" :data="data" :campaign="campaign" :busy="busy" :initial-quadrant="String(route.query.quadrant||'strengths')" @command="run"/><section v-if="campaign.status==='open'&&campaign.quota_mode==='legacy'" class="sq-card p-3 mb-3"><h2 class="h5">Contribuir para a recolha</h2><form novalidate @submit.prevent="add"><div class="d-flex gap-2 mb-2"><select v-model="contribution.quadrant" class="form-select" aria-label="Quadrante"><option v-for="(label,q) in quadrants" :key="q" :value="q">{{label}}</option></select><select v-model="contribution.team_id" class="form-select" aria-label="Equipa"><option value="">Sem equipa indicada</option><option v-for="t in data.teams" :key="t.id" :value="t.id">{{t.name}}</option></select></div><textarea v-model="contribution.contribution" class="form-control mb-2" aria-label="Contributo original" placeholder="Escreve uma ideia por contributo"/><button class="btn btn-primary" :disabled="busy">Enviar contributo</button></form>
<details v-if="auth.canManageStrategy" class="mt-3"><summary>Importar contributos de uma folha de cálculo</summary><p>Copia as linhas, sem cabeçalhos, com quatro colunas: quadrante, texto, autor e equipa (opcional). Os duplicados são preservados.</p><textarea v-model="importText" class="form-control mb-2" rows="5" aria-label="Linhas para importar"/><button class="btn btn-outline-primary" :disabled="busy" @click="importRows">Importar linhas</button></details></section>
<section v-if="campaign.quota_mode==='legacy'" class="sq-card p-3 mb-3"><h2 class="h5">Contributos originais · {{originals.length}}</h2><p v-if="!originals.length">Ainda não existem contributos.</p><div v-for="r in originals" :key="r.id" class="border-bottom py-2"><strong>{{quadrants[r.quadrant]}}</strong> · {{r.author_label}} · {{r.source}}<span v-if="r.team_id"> · {{data.teams?.find((t:any)=>t.id===r.team_id)?.name}}</span><p class="mb-0" style="white-space:pre-wrap">{{r.contribution}}</p><small>{{r.item_id?'Consolidado na SWOT oficial':'Por consolidar'}}</small></div></section>
<section v-if="auth.canManageStrategy" class="sq-card p-3 mb-3"><h2 class="h5">Consolidação com revisão humana</h2><p>A sugestão agrupa textos iguais e redações com vocabulário semelhante. Não substitui a análise humana. Podes ajustar o texto final e o quadrante antes de aprovar.</p><button v-if="campaign.status==='validation'" class="btn btn-outline-primary mb-3" :disabled="busy" @click="run(()=>strategyAdminCommand('propose_groups',selected,{}))">Sugerir grupos</button><div v-for="p in proposals" :key="p.id" class="border rounded p-3 mb-2"><p>{{data.strategy_thematic_areas?.find((a:any)=>a.id===p.thematic_area_id)?.name}} · {{p.contribution_ids.length}} menções · {{p.status==='validated'?'Validado':'A rever'}}</p><details class="mb-2"><summary>Rever originais e possíveis reclassificações</summary><p v-for="r in originals.filter((r:any)=>p.contribution_ids.includes(r.id))" :key="r.id">{{quadrants[r.quadrant]}} · {{r.author_label}}: {{r.contribution}} <strong v-if="r.quadrant!==p.quadrant">— confirmar reclassificação</strong></p></details><select v-model="p.quadrant" class="form-select mb-2" :disabled="p.status==='validated'" aria-label="Quadrante final"><option v-for="(label,q) in quadrants" :key="q" :value="q">{{label}}</option></select><textarea v-model="p.title" class="form-control mb-2" :disabled="p.status==='validated'" aria-label="Texto final"/><button v-if="p.status==='proposed'&&campaign.status==='validation'" class="btn btn-primary" :disabled="busy" @click="validate(p)">Rever e publicar na SWOT oficial</button></div></section>
<details class="sq-card p-3"><summary>Histórico da campanha</summary><p v-for="h in data.history?.filter((r:any)=>r.entity_id===selected)" :key="h.id">{{new Date(h.created_at).toLocaleString('pt-PT')}} · {{({create:'Campanha criada',edit:'Configuração alterada',state:'Estado alterado',collect:'Contributos guardados',complete_exception:'Participação concluída com exceção',import:'Lote importado',upgrade:'Regras atualizadas',submit:'Participação submetida',context_review:'Contexto validado',propose:'Grupos sugeridos',validate:'Grupo publicado'} as Record<string,string>)[h.action]||'Alteração registada'}} · {{data.profiles?.find((u:any)=>u.id===h.actor_id)?.full_name||'Utilizador'}} <span v-if="h.after_data?.reason">· {{h.after_data.reason}}</span></p></details></template></div></template>

<style scoped>
.campaign-page {min-width:0;overflow-wrap:anywhere}.campaign-page select,.campaign-page input {max-width:100%}.campaign-page .d-flex > * {min-width:0}
</style>
